#include "revenge/loader.hpp"
#include <iostream>
#include <stdexcept>
using namespace revenge;
void put(LoadPlan& p,size_t at,uint64_t v,unsigned n){for(unsigned i=0;i<n;++i)p.mapped.at(at+i)=uint8_t(v>>(8*i));}
void check(bool b){if(!b)throw std::runtime_error("unwind slots assertion");}
int main(){try{LoadPlan p;p.image.image_size=0x4000;p.image.base=p.mapped_base=0x140000000ull;p.header_bytes=0x200;p.mapped.resize(0x4000);p.image.sections={{"text",0x1000,0x1000,0,0,0x60000000},{"data",0x2000,0x1000,0,0,0xc0000000},{"rdata",0x3000,0x1000,0,0,0x40000000}};put(p,0x3c,0x80,4);put(p,0x94,240,2);size_t opt=0x98;put(p,opt+108,16,4);put(p,opt+112+9*8,0x3000,4);put(p,opt+116+9*8,40,4);put(p,0x3000,p.mapped_base+0x2050,8);put(p,0x3008,p.mapped_base+0x2070,8);put(p,0x3010,p.mapped_base+0x2000,8);put(p,opt+112+3*8,0x3080,4);put(p,opt+116+3*8,12,4);put(p,0x3080,0x1010,4);put(p,0x3084,0x1040,4);put(p,0x3088,0x3100,4);put(p,0x3100,1,1);put(p,0x3101,16,1);put(p,0x3102,4,1);
put(p,0x3104,12,1);put(p,0x3105,1,1);put(p,0x3106,32,2);put(p,0x3108,8,1);put(p,0x3109,0x32,1);put(p,0x310a,1,1);put(p,0x310b,0x30,1);
auto report=[&]{return init_metadata_report(p);};auto s=report();check(s.find("TLS raw template extent: 32; readable occupied template: 1")!=std::string::npos);check(s.find("records checked=1; operations=3; suspicious slot records=0; other versions skipped=0; maximum local stack adjustment=296")!=std::string::npos);put(p,0x3102,1,1);check(report().find("suspicious slot records=1")!=std::string::npos);put(p,0x3102,4,1);put(p,0x3108,15,1);check(report().find("suspicious slot records=1")!=std::string::npos);put(p,0x3108,8,1);put(p,0x3109,6,1);check(report().find("suspicious slot records=1")!=std::string::npos);put(p,0x3100,2,1);check(report().find("other versions skipped=1")!=std::string::npos);std::cout<<"Unwind slots: v1 allocation sizes, ordering, truncated and reserved operations, v2 skip and TLS template extent passed.\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
